mapper.select:
select *
from t_questionnaire tq
where tq.is_deleted = 0
    and tq.experiment_plan_id = #{dto.experimentPlanId}

        and tq.questionnaire_attribution = #{userName}

SELECT jt.choices choicesArray
FROM t_questionnaire_data tqa,
     JSON_TABLE(
             qa_data,
             '$[*]' COLUMNS ( answerSort LONG PATH '$.answerSort', choices JSON PATH '$.choices' )) AS jt
WHERE tqa.groups_id = #{groupsId}
  and tqa.is_deleted = 0
  AND tqa.questionnaire_id = #{questionnaireId}
  AND jt.answerSort = #{questionSort}
  AND jt.choices IS NOT NULL

SELECT jt.answerContext
FROM t_questionnaire_data tqa,
     JSON_TABLE(
             qa_data,
             '$[*]' COLUMNS ( answerSort LONG PATH '$.answerSort', answerContext TEXT PATH '$.answerContext' )) AS jt
WHERE tqa.is_deleted = 0
  and tqa.groups_id = #{groupsId}
  AND tqa.questionnaire_id = #{questionnaireId}
  AND jt.answerSort = #{questionSort}
  AND jt.answerContext IS NOT NULL

select count(*)
from t_questionnaire_record
where is_deleted = 0
  and groups_id = #{groupsId}
  and question_sort = #{questionSort}
  and questionnaire_id = #{questionnaireId}

select answer wordName,
       count(id) wordNum
from t_questionnaire_record
where is_deleted = 0
  and groups_id = #{groupsId}
  and question_sort = #{questionSort}
  and questionnaire_id = #{questionnaireId}
group by answer
order by answer

select tq.*, ep.experiment_name as experiment_plan_name, ep.experiment_title as experiment_plan_title, case when f.id is not null then 1 else 0 end as is_favorite from t_questionnaire tq left join t_experiment_plan ep on tq.experiment_plan_id = ep.id and ep.is_deleted = 0 left join t_favorite f on tq.id = f.target_id and f.favorite_type = 'QUESTIONNAIRE' and f.user_id = #{userId} and f.is_deleted = 0 where tq.is_deleted = 0 and tq.status = 'OPEN'
and tq.questionnaire_attribution = #{questionnaireAttribution}
order by tq.update_date desc
